#include "args.h"

#include <cstdlib>
#include <iostream>
#include <stdexcept>
#include <unordered_map>

namespace ft {

Args::Args() {
  lr = 0.05;
  dim = 100;
  ws = 5;
  epoch = 5;
  minCount = 5;
  minCountLabel = 0;
  neg = 5;
  wordNgrams = 1;
  loss = LossKind::ns;
  model = ModelKind::sg;
  bucket = 2000000;
  minn = 3;
  maxn = 6;
  thread = 12;
  lrUpdateRate = 100;
  t = 1e-4;
  label = "__label__";
  verbose = 2;
  pretrainedVectors = "";
  saveOutput = false;
  seed = 0;

  qout = false;
  retrain = false;
  qnorm = false;
  cutoff = 0;
  dsub = 2;

  autotuneValidationFile = "";
  autotuneMetric = "f1";
  autotunePredictions = 1;
  autotuneDuration = 60 * 5;
  autotuneModelSize = "";
}

std::string Args::lossToString(LossKind ln) const {
  switch (ln) {
    case LossKind::hs:
      return "hs";
    case LossKind::ns:
      return "ns";
    case LossKind::softmax:
      return "softmax";
    case LossKind::ova:
      return "one-vs-all";
  }
  return "Unknown loss!";
}

std::string Args::boolToString(bool b) const {
  return b ? "true" : "false";
}

std::string Args::modelToString(ModelKind mn) const {
  switch (mn) {
    case ModelKind::cbow:
      return "cbow";
    case ModelKind::sg:
      return "sg";
    case ModelKind::sup:
      return "sup";
  }
  return "Unknown model name!";
}

std::string Args::metricToString(MetricKind mn) const {
  switch (mn) {
    case MetricKind::f1score:
      return "f1score";
    case MetricKind::f1scoreLabel:
      return "f1scoreLabel";
  }
  return "Unknown metric name!";
}

void Args::parseArgs(const std::vector<std::string>& args) {
  std::string command(args[1]);
  if (command == "supervised") {
    model = ModelKind::sup;
    loss = LossKind::softmax;
    minCount = 1;
    minn = 0;
    maxn = 0;
    lr = 0.1;
  } else if (command == "cbow") {
    model = ModelKind::cbow;
  }
  for (size_t ai = 2; ai < args.size(); ai += 2) {
    if (args[ai][0] != '-') {
      std::cerr << "Provided argument without a dash! Usage:" << std::endl;
      printHelp();
      exit(EXIT_FAILURE);
    }
    try {
      setManual(args[ai].substr(1));
      const std::string& a = args[ai];
      if (a == "-h") {
        std::cerr << "Here is the help! Usage:" << std::endl;
        printHelp();
        exit(EXIT_FAILURE);
      } else if (a == "-input") {
        input = std::string(args.at(ai + 1));
      } else if (a == "-output") {
        output = std::string(args.at(ai + 1));
      } else if (a == "-lr") {
        lr = std::stof(args.at(ai + 1));
      } else if (a == "-lrUpdateRate") {
        lrUpdateRate = std::stoi(args.at(ai + 1));
      } else if (a == "-dim") {
        dim = std::stoi(args.at(ai + 1));
      } else if (a == "-ws") {
        ws = std::stoi(args.at(ai + 1));
      } else if (a == "-epoch") {
        epoch = std::stoi(args.at(ai + 1));
      } else if (a == "-minCount") {
        minCount = std::stoi(args.at(ai + 1));
      } else if (a == "-minCountLabel") {
        minCountLabel = std::stoi(args.at(ai + 1));
      } else if (a == "-neg") {
        neg = std::stoi(args.at(ai + 1));
      } else if (a == "-wordNgrams") {
        wordNgrams = std::stoi(args.at(ai + 1));
      } else if (a == "-loss") {
        const std::string& v = args.at(ai + 1);
        if (v == "hs") {
          loss = LossKind::hs;
        } else if (v == "ns") {
          loss = LossKind::ns;
        } else if (v == "softmax") {
          loss = LossKind::softmax;
        } else if (v == "one-vs-all" || v == "ova") {
          loss = LossKind::ova;
        } else {
          std::cerr << "Unknown loss: " << v << std::endl;
          printHelp();
          exit(EXIT_FAILURE);
        }
      } else if (a == "-bucket") {
        bucket = std::stoi(args.at(ai + 1));
      } else if (a == "-minn") {
        minn = std::stoi(args.at(ai + 1));
      } else if (a == "-maxn") {
        maxn = std::stoi(args.at(ai + 1));
      } else if (a == "-thread") {
        thread = std::stoi(args.at(ai + 1));
      } else if (a == "-t") {
        t = std::stof(args.at(ai + 1));
      } else if (a == "-label") {
        label = std::string(args.at(ai + 1));
      } else if (a == "-verbose") {
        verbose = std::stoi(args.at(ai + 1));
      } else if (a == "-pretrainedVectors") {
        pretrainedVectors = std::string(args.at(ai + 1));
      } else if (a == "-saveOutput") {
        saveOutput = true;
        ai--;
      } else if (a == "-seed") {
        seed = std::stoi(args.at(ai + 1));
      } else if (a == "-qnorm") {
        qnorm = true;
        ai--;
      } else if (a == "-retrain") {
        retrain = true;
        ai--;
      } else if (a == "-qout") {
        qout = true;
        ai--;
      } else if (a == "-cutoff") {
        cutoff = std::stoi(args.at(ai + 1));
      } else if (a == "-dsub") {
        dsub = std::stoi(args.at(ai + 1));
      } else if (a == "-autotune-validation") {
        autotuneValidationFile = std::string(args.at(ai + 1));
      } else if (a == "-autotune-metric") {
        autotuneMetric = std::string(args.at(ai + 1));
        getAutotuneMetric();  // throws on invalid metric
      } else if (a == "-autotune-predictions") {
        autotunePredictions = std::stoi(args.at(ai + 1));
      } else if (a == "-autotune-duration") {
        autotuneDuration = std::stoi(args.at(ai + 1));
      } else if (a == "-autotune-modelsize") {
        autotuneModelSize = std::string(args.at(ai + 1));
      } else {
        std::cerr << "Unknown argument: " << args[ai] << std::endl;
        printHelp();
        exit(EXIT_FAILURE);
      }
    } catch (std::out_of_range&) {
      std::cerr << args[ai] << " is missing an argument" << std::endl;
      printHelp();
      exit(EXIT_FAILURE);
    }
  }
  if (input.empty() || output.empty()) {
    std::cerr << "Empty input or output path." << std::endl;
    printHelp();
    exit(EXIT_FAILURE);
  }
  if (wordNgrams <= 1 && maxn == 0 && !hasAutotune()) {
    bucket = 0;
  }
}

void Args::printHelp() {
  printBasicHelp();
  printDictionaryHelp();
  printTrainingHelp();
  printAutotuneHelp();
  printQuantizationHelp();
}

void Args::printBasicHelp() {
  std::cerr << "\nThe following arguments are mandatory:\n"
            << "  -input              training file path\n"
            << "  -output             output file path\n"
            << "\nThe following arguments are optional:\n"
            << "  -verbose            verbosity level [" << verbose << "]\n";
}

void Args::printDictionaryHelp() {
  std::cerr << "\nThe following arguments for the dictionary are optional:\n"
            << "  -minCount           minimal number of word occurences ["
            << minCount << "]\n"
            << "  -minCountLabel      minimal number of label occurences ["
            << minCountLabel << "]\n"
            << "  -wordNgrams         max length of word ngram [" << wordNgrams
            << "]\n"
            << "  -bucket             number of buckets [" << bucket << "]\n"
            << "  -minn               min length of char ngram [" << minn
            << "]\n"
            << "  -maxn               max length of char ngram [" << maxn
            << "]\n"
            << "  -t                  sampling threshold [" << t << "]\n"
            << "  -label              labels prefix [" << label << "]\n";
}

void Args::printTrainingHelp() {
  std::cerr
      << "\nThe following arguments for training are optional:\n"
      << "  -lr                 learning rate [" << lr << "]\n"
      << "  -lrUpdateRate       change the rate of updates for the learning "
         "rate ["
      << lrUpdateRate << "]\n"
      << "  -dim                size of word vectors [" << dim << "]\n"
      << "  -ws                 size of the context window [" << ws << "]\n"
      << "  -epoch              number of epochs [" << epoch << "]\n"
      << "  -neg                number of negatives sampled [" << neg << "]\n"
      << "  -loss               loss function {ns, hs, softmax, one-vs-all} ["
      << lossToString(loss) << "]\n"
      << "  -thread             number of threads (set to 1 to ensure "
         "reproducible results) ["
      << thread << "]\n"
      << "  -pretrainedVectors  pretrained word vectors for supervised "
         "learning ["
      << pretrainedVectors << "]\n"
      << "  -saveOutput         whether output params should be saved ["
      << boolToString(saveOutput) << "]\n"
      << "  -seed               random generator seed  [" << seed << "]\n";
}

void Args::printAutotuneHelp() {
  std::cerr << "\nThe following arguments are for autotune:\n"
            << "  -autotune-validation            validation file to be used "
               "for evaluation\n"
            << "  -autotune-metric                metric objective {f1, "
               "f1:labelname} ["
            << autotuneMetric << "]\n"
            << "  -autotune-predictions           number of predictions used "
               "for evaluation  ["
            << autotunePredictions << "]\n"
            << "  -autotune-duration              maximum duration in seconds ["
            << autotuneDuration << "]\n"
            << "  -autotune-modelsize             constraint model file size ["
            << autotuneModelSize << "] (empty = do not quantize)\n";
}

void Args::printQuantizationHelp() {
  std::cerr
      << "\nThe following arguments for quantization are optional:\n"
      << "  -cutoff             number of words and ngrams to retain ["
      << cutoff << "]\n"
      << "  -retrain            whether embeddings are finetuned if a cutoff "
         "is applied ["
      << boolToString(retrain) << "]\n"
      << "  -qnorm              whether the norm is quantized separately ["
      << boolToString(qnorm) << "]\n"
      << "  -qout               whether the classifier is quantized ["
      << boolToString(qout) << "]\n"
      << "  -dsub               size of each sub-vector [" << dsub << "]\n";
}

void Args::save(std::ostream& out) {
  out.write((char*)&(dim), sizeof(int));
  out.write((char*)&(ws), sizeof(int));
  out.write((char*)&(epoch), sizeof(int));
  out.write((char*)&(minCount), sizeof(int));
  out.write((char*)&(neg), sizeof(int));
  out.write((char*)&(wordNgrams), sizeof(int));
  out.write((char*)&(loss), sizeof(LossKind));
  out.write((char*)&(model), sizeof(ModelKind));
  out.write((char*)&(bucket), sizeof(int));
  out.write((char*)&(minn), sizeof(int));
  out.write((char*)&(maxn), sizeof(int));
  out.write((char*)&(lrUpdateRate), sizeof(int));
  out.write((char*)&(t), sizeof(double));
}

void Args::load(std::istream& in) {
  in.read((char*)&(dim), sizeof(int));
  in.read((char*)&(ws), sizeof(int));
  in.read((char*)&(epoch), sizeof(int));
  in.read((char*)&(minCount), sizeof(int));
  in.read((char*)&(neg), sizeof(int));
  in.read((char*)&(wordNgrams), sizeof(int));
  in.read((char*)&(loss), sizeof(LossKind));
  in.read((char*)&(model), sizeof(ModelKind));
  in.read((char*)&(bucket), sizeof(int));
  in.read((char*)&(minn), sizeof(int));
  in.read((char*)&(maxn), sizeof(int));
  in.read((char*)&(lrUpdateRate), sizeof(int));
  in.read((char*)&(t), sizeof(double));
}

void Args::dump(std::ostream& out) const {
  out << "dim"
      << " " << dim << std::endl;
  out << "ws"
      << " " << ws << std::endl;
  out << "epoch"
      << " " << epoch << std::endl;
  out << "minCount"
      << " " << minCount << std::endl;
  out << "neg"
      << " " << neg << std::endl;
  out << "wordNgrams"
      << " " << wordNgrams << std::endl;
  out << "loss"
      << " " << lossToString(loss) << std::endl;
  out << "model"
      << " " << modelToString(model) << std::endl;
  out << "bucket"
      << " " << bucket << std::endl;
  out << "minn"
      << " " << minn << std::endl;
  out << "maxn"
      << " " << maxn << std::endl;
  out << "lrUpdateRate"
      << " " << lrUpdateRate << std::endl;
  out << "t"
      << " " << t << std::endl;
}

bool Args::hasAutotune() const {
  return !autotuneValidationFile.empty();
}

bool Args::isManual(const std::string& argName) const {
  return (manualArgs_.count(argName) != 0);
}

void Args::setManual(const std::string& argName) {
  manualArgs_.emplace(argName);
}

MetricKind Args::getAutotuneMetric() const {
  if (autotuneMetric.substr(0, 3) == "f1:") {
    return MetricKind::f1scoreLabel;
  } else if (autotuneMetric == "f1") {
    return MetricKind::f1score;
  }
  throw std::runtime_error("Unknown metric : " + autotuneMetric);
}

std::string Args::getAutotuneMetricLabel() const {
  MetricKind metric = getAutotuneMetric();
  std::string label;
  if (metric == MetricKind::f1scoreLabel) {
    label = autotuneMetric.substr(3);
  }
  if (label.empty()) {
    throw std::runtime_error("Empty metric label : " + autotuneMetric);
  }
  return label;
}

double Args::getAutotuneMetricValue() const {
  return 0.0;
}

int64_t Args::getAutotuneModelSize() const {
  std::string modelSize = autotuneModelSize;
  if (modelSize.empty()) {
    return Args::kUnlimitedModelSize;
  }
  std::unordered_map<char, int> units = {
      {'k', 1000},
      {'K', 1000},
      {'m', 1000000},
      {'M', 1000000},
      {'g', 1000000000},
      {'G', 1000000000},
  };
  uint64_t multiplier = 1;
  char lastCharacter = modelSize.back();
  if (units.count(lastCharacter)) {
    multiplier = units[lastCharacter];
    modelSize = modelSize.substr(0, modelSize.size() - 1);
  }
  uint64_t size = 0;
  size_t nonNumericCharacter = 0;
  bool parseError = false;
  try {
    size = std::stol(modelSize, &nonNumericCharacter);
  } catch (std::invalid_argument&) {
    parseError = true;
  }
  if (!parseError && nonNumericCharacter != modelSize.size()) {
    parseError = true;
  }
  if (parseError) {
    throw std::invalid_argument(
        "Unable to parse model size " + autotuneModelSize);
  }
  return size * multiplier;
}

}  // namespace ft
EOF"}

