DenseMatrix::DenseMatrix() : Matrix(0, 0), data_() {}

DenseMatrix::DenseMatrix(int64_t m, int64_t n) : Matrix(m, n), data_() {
  allocate();
}

DenseMatrix::DenseMatrix(DenseMatrix&& other) noexcept
    : Matrix(other.m_, other.n_), data_(std::move(other.data_)) {}

void DenseMatrix::allocate() {
  data_.reset(new real[m_ * n_]);
}

void DenseMatrix::zero() {
  std::fill(data_.get(), data_.get() + m_ * n_, 0.0);
}

void DenseMatrix::uniformBlock(real a, int block, int32_t seed) {
  std::minstd_rand rng(block + seed);
  std::uniform_real_distribution<> uniform(-a, a);
  int64_t blockSize = (m_ * n_) / 10;
  for (int64_t i = blockSize * block;
       i < (m_ * n_) && i < blockSize * (block + 1);
       i++) {
    data_[i] = uniform(rng);
  }
}

void DenseMatrix::uniform(real a, unsigned int thread, int32_t seed) {
  if (thread > 1) {
    std::vector<std::thread> workers;
    for (int i = 0; i < (int)thread; i++) {
      workers.push_back(std::thread([=]() { uniformBlock(a, i, seed); }));
    }
    for (size_t i = 0; i < workers.size(); i++) {
      workers[i].join();
    }
  } else {
    uniformBlock(a, 0, seed);
  }
}

void DenseMatrix::multiplyRow(const Vector& nums, int64_t ib, int64_t ie) {
  if (ie == -1) {
    ie = m_;
  }
  for (auto i = ib; i < ie; i++) {
    real n = nums[i - ib];
    if (n != 0) {
      for (auto j = 0; j < n_; j++) {
        at(i, j) *= n;
      }
    }
  }
}

void DenseMatrix::divideRow(const Vector& denoms, int64_t ib, int64_t ie) {
  if (ie == -1) {
    ie = m_;
  }
  for (auto i = ib; i < ie; i++) {
    real n = denoms[i - ib];
    if (n != 0) {
      for (auto j = 0; j < n_; j++) {
        at(i, j) /= n;
      }
    }
  }
}

real DenseMatrix::l2NormRow(int64_t i) const {
  auto norm = 0.0;
  for (auto j = 0; j < n_; j++) {
    norm += at(i, j) * at(i, j);
  }
  if (std::isnan(norm)) {
    throw EncounteredNaNError();
  }
  return std::sqrt(norm);
}

void DenseMatrix::l2NormRow(Vector& norms) const {
  for (auto i = 0; i < m_; i++) {
    norms[i] = l2NormRow(i);
  }
}

real DenseMatrix::dotRow(const Vector& vec, int64_t i) const {
  real d = 0.0;
  const real* row = data_.get() + i * n_;
  for (int64_t j = 0; j < n_; j++) {
    d += row[j] * vec[j];
  }
  if (std::isnan(d)) {
    throw EncounteredNaNError();
  }
  return d;
}

void DenseMatrix::addVectorToRow(const Vector& vec, int64_t i, real a) {
  real* row = data_.get() + i * n_;
  for (int64_t j = 0; j < n_; j++) {
    row[j] += a * vec[j];
  }
}

void DenseMatrix::addRowToVector(Vector& x, int32_t i) const {
  const real* row = data_.get() + int64_t(i) * n_;
  for (int64_t j = 0; j < n_; j++) {
    x[j] += row[j];
  }
}

void DenseMatrix::addRowToVector(Vector& x, int32_t i, real a) const {
  const real* row = data_.get() + int64_t(i) * n_;
  for (int64_t j = 0; j < n_; j++) {
    x[j] += a * row[j];
  }
}

